"""Travel notice tools."""

from __future__ import annotations

from rasa.mantle.tools.decorator import ToolContext, tool
from rasa.mantle.tools.result import ToolResult

# Destinations where card acceptance is limited in this demo dataset.
_HIGH_RISK_DESTINATIONS = frozenset(
    {
        "atlantis",
        "el dorado",
        "shangri-la",
        "wakanda",
    }
)


@tool(
    description=(
        "Check card support at the customer's travel destination. Call once "
        "after the destination is recorded; records whether the destination "
        "has limited card acceptance."
    )
)
async def check_destination_risk(context: ToolContext = None) -> ToolResult:
    destination = str(context.memory.get("destination") or "").strip().lower()
    if not destination:
        return ToolResult(
            llm_response={"error": "No destination recorded yet."},
        )

    high_risk = any(name in destination for name in _HIGH_RISK_DESTINATIONS)
    context.memory.set("destination_high_risk", high_risk)
    context.memory.set("risk_checked", True)
    return ToolResult(llm_response={"destination_high_risk": high_risk})


@tool(
    description=(
        "File the travel notice for the selected card after the customer "
        "confirmed the recap. Returns the notice confirmation number."
    )
)
async def submit_travel_notice(context: ToolContext = None) -> ToolResult:
    destination = context.memory.get("destination")
    travel_dates = context.memory.get("travel_dates")
    if not destination or not travel_dates:
        return ToolResult(
            llm_response={
                "error": "Destination and travel dates must be recorded first.",
            }
        )

    context.memory.set("notice_submitted", True)
    return ToolResult(
        llm_response={
            "notice_submitted": True,
            "confirmation_number": "TN-2026-0042",
        }
    )
